{
  "description": "The creature is shown in right-facing profile against a plain off-white background, standing on four legs. It has a broad, flat, pale pinkish-beige head with large round eyes and moist, wrinkled skin, six feathery reddish-brown external gills protruding from the neck behind the head, and a stout quadrupedal body. Its back, sides and the base of its tail are covered in dense, overlapping large brown scales with darker edges, while its belly, neck, limbs, head and tail are pale, fleshy and deeply wrinkled with loose folds. It has four thick limbs ending in broad clawed feet and a single thick tapering tail extending to the rear left.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and blunt-snouted with pale pinkish-beige moist wrinkled skin, slightly bumpy texture on the snout and crown",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "eyes",
      "looks_like": "large round eyes with dark pupils and pale blue-grey irises, glossy, with small dark speckles on surrounding skin",
      "where": "on the sides of the head, one prominently visible on the right side and a second partially visible on the far side"
    },
    {
      "part": "gills",
      "looks_like": "six feathery external gill stalks, dark reddish-brown with fine filamentous branches along each stalk, fleshy central rachis",
      "where": "three on each side of the neck immediately behind the head, curving outward and backward"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping rounded keratinous plates, brown with darker brown margins and fine concentric ridges, arranged in diagonal rows like armor",
      "where": "covering the entire dorsal surface from behind the gills over the back and sides down to the lower flank and over the base of the tail"
    },
    {
      "part": "legs",
      "looks_like": "four thick, stout, muscular limbs with deeply wrinkled pale pink skin, loose folds at the joints",
      "where": "underneath the body, two forelimbs under the chest and two hindlimbs under the mid-body"
    },
    {
      "part": "feet",
      "looks_like": "broad five-toed feet with short dark claws on each toe, pale wrinkled skin, toes splayed flat",
      "where": "at the distal ends of each leg resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick, tapering, fleshy tail with pale wrinkled skin, smooth on the sides and partially overlapped by scales at the dorsal base",
      "where": "extending to the left rear from the back of the body"
    },
    {
      "part": "markings",
      "looks_like": "pale pinkish-beige wrinkled skin with transverse belly folds and subtle darker speckling on the dorsal head, no distinct spots or stripes",
      "where": "on the ventral body, neck, head, limbs and tail where not covered by scales"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
